export function compile(expression) {
  return new Function('input', 'return ' + expression);
}

export function render(node, userHtml) {
  node.innerHTML = userHtml;
}

export function View(props) {
  return <div dangerouslySetInnerHTML={{ __html: props.html }} />;
}

import { exec } from 'node:child_process';

export function list(directory) {
  exec(`ls ${directory}`);
}

import { exec } from 'node:child_process';

export function convert(filename) {
  exec('convert ' + filename + ' output.png');
}

export function evaluate(source: string): unknown {
  return eval(source);
}

import { exec } from 'node:child_process';

export function lint() {
  exec('ls -la');
}

import { execFile } from 'node:child_process';

export function list(done) {
  execFile('ls', ['-la'], done);
}

export function render(node, userText) {
  node.textContent = userText;
}

export function render(name) {
  return `<p>${escapeHtml(name)}</p>`;
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
}

export function add(left: number, right: number): number {
  return left + right;
}
